WITH filtered AS MATERIALIZED (SELECT o.id, o.customer_id, o.created_at FROM orders AS o WHERE lower(o.status) = 'completed' AND o.created_at::date >= DATE '2024-01-01'), eligible AS (SELECT DISTINCT fo.customer_id FROM filtered AS fo JOIN order_items AS oi ON oi.order_id = fo.id JOIN products AS p ON p.id = oi.product_id JOIN product_suppliers AS ps ON ps.product_id = p.id JOIN suppliers AS s ON s.id = ps.supplier_id JOIN shipments AS sh ON sh.order_id = fo.id WHERE p.active AND s.risk_tier >= 4 AND (sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days')), captured AS (SELECT fo.id, fo.customer_id FROM filtered AS fo WHERE EXISTS (SELECT 1 FROM payments AS pay WHERE pay.order_id = fo.id AND pay.status = 'captured')), ca AS (SELECT customer_id, count(*) AS n FROM captured GROUP BY customer_id), na AS (SELECT x.customer_id, sum((oi.quantity - COALESCE(r.quantity, 0)) * oi.unit_price) AS v FROM captured AS x JOIN order_items AS oi ON oi.order_id = x.id LEFT JOIN returns AS r ON r.order_id = oi.order_id AND r.line_no = oi.line_no GROUP BY x.customer_id), pa AS (SELECT fo.customer_id, sum(op.discount_amount) AS v FROM filtered AS fo JOIN order_promotions AS op ON op.order_id = fo.id JOIN promotions AS pr ON pr.id = op.promotion_id WHERE pr.active GROUP BY fo.customer_id), la AS (SELECT fo.customer_id, count(*) AS n FROM filtered AS fo JOIN shipments AS sh ON sh.order_id = fo.id WHERE sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days' GROUP BY fo.customer_id), ra AS (SELECT fo.customer_id, count(DISTINCT ps.supplier_id) AS n FROM filtered AS fo JOIN order_items AS oi ON oi.order_id = fo.id JOIN product_suppliers AS ps ON ps.product_id = oi.product_id JOIN suppliers AS s ON s.id = ps.supplier_id WHERE s.risk_tier >= 4 GROUP BY fo.customer_id), ma AS (SELECT customer_id, max(created_at) AS t FROM filtered GROUP BY customer_id) SELECT c.id AS customer_id, c.region, c.segment, COALESCE(ca.n, 0) AS captured_order_count, COALESCE(na.v, 0)::numeric(20, 2) AS net_item_revenue, COALESCE(pa.v, 0)::numeric(18, 2) AS active_promotion_discount, COALESCE(la.n, 0) AS late_shipment_count, COALESCE(ra.n, 0) AS risky_supplier_count, ma.t AS last_completed_at FROM customers AS c JOIN eligible AS e ON e.customer_id = c.id LEFT JOIN ca ON ca.customer_id = c.id LEFT JOIN na ON na.customer_id = c.id LEFT JOIN pa ON pa.customer_id = c.id LEFT JOIN la ON la.customer_id = c.id LEFT JOIN ra ON ra.customer_id = c.id LEFT JOIN ma ON ma.customer_id = c.id WHERE c.active